// Auditor System Health Check — every 30 min
// Catches broken automations, misassigned issues, rule violations
// Posts alerts to #agent-logs only when something is wrong

const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const MC_API = 'http://localhost:3000/api/issues';
const N8N_KEY = 'n8n_api_34e5ba0e4da8b759e75b310a8c014c4de0275375eba302bdf87d2e7e6dd2adac';
const DISCORD_TOKEN = process.env.DISCORD_TOKEN || '';
const ALERT_CHANNEL = '1485333335868834063'; // #alerts

const alerts = [];
const now = Date.now();

// ── 1. Check critical n8n workflows ──
const CRITICAL_WORKFLOWS = [
  { id: 'ypkSfCq0LZ6eXDvM', name: 'Auto-Activate on Open', maxErrorStreak: 3 },
  { id: '0EwpBAD0npXKhUrW', name: 'Tester Loop', maxErrorStreak: 3 },
  { id: 'tgwln7Ra04hKhbeC', name: 'In-Review Trigger', maxErrorStreak: 3 },
  { id: 'TYNZOhpgz5FHaog5', name: 'KAOS Reroute', maxErrorStreak: 3 },
  { id: 'ao4Y4wryLRGpa6F5', name: 'Auto-Trigger Deployer', maxErrorStreak: 3 },
  { id: 'huC16MvkjX5FiI3f', name: 'PR Merge → Released', maxErrorStreak: 3 },
];

for (const wf of CRITICAL_WORKFLOWS) {
  try {
    const runs = await helpers.httpRequest({
      method: 'GET',
      url: 'http://localhost:5678/api/v1/executions?workflowId=' + wf.id + '&limit=5',
      headers: { 'X-N8N-API-KEY': N8N_KEY }
    });
    const execs = runs.data || [];
    if (!execs.length) { alerts.push('⚠️ **' + wf.name + '**: no executions found'); continue; }
    const errors = execs.filter(e => e.status === 'error').length;
    if (errors >= wf.maxErrorStreak) {
      alerts.push('🔴 **' + wf.name + '**: ' + errors + '/' + execs.length + ' recent runs errored');
    }
    // Check if workflow is active
    const wfData = await helpers.httpRequest({
      method: 'GET', url: 'http://localhost:5678/api/v1/workflows/' + wf.id,
      headers: { 'X-N8N-API-KEY': N8N_KEY }
    });
    if (!wfData.active) alerts.push('🔴 **' + wf.name + '**: workflow is INACTIVE — should be ON');
  } catch(e) {
    alerts.push('❌ **' + wf.name + '**: health check failed — ' + e.message);
  }
}

// ── 2. Check for issues misassigned to main/kaos-claude (non-epic, active) ──
const ACTIVE = ['open','in_progress','code_review','in_review','product_review','approved'];
const misassigned = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=in.(' + ACTIVE.join(',') + ')&assignee=in.(main,kaos-claude)&type=neq.epic&select=task_key,title,type,assignee,status',
  headers: h
});
if (Array.isArray(misassigned) && misassigned.length > 0) {
  alerts.push('🟡 **Misassigned to KAOS**: ' + misassigned.length + ' non-epic issues assigned to main/kaos-claude: ' +
    misassigned.map(i => '`' + i.task_key + '`(' + i.type + ')').join(', '));
}

// ── 3. Issues stuck in code_review > 2h with no tester activity ──
const twoHoursAgo = new Date(now - 2 * 60 * 60 * 1000).toISOString();
const stuckReview = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.code_review&tester_status=eq.pending&updated_at=lt.' + twoHoursAgo + '&select=task_key,title,assignee,updated_at&limit=5',
  headers: h
});
if (Array.isArray(stuckReview) && stuckReview.length > 0) {
  alerts.push('🟡 **Stuck in code_review >2h**: ' + stuckReview.map(i => '`' + i.task_key + '`').join(', ') + ' — tester not responding');
}

// ── 4. Issues in open with started_at set but no in_progress (stuck trigger) ──
const stuckOpen = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.open&started_at=not.is.null&select=task_key,assignee,started_at&limit=10',
  headers: h
});
if (Array.isArray(stuckOpen) && stuckOpen.length > 0) {
  alerts.push('🟡 **Open issues with started_at set** (' + stuckOpen.length + '): trigger fired but agent never claimed — ' +
    stuckOpen.map(i => '`' + i.task_key + '`(' + i.assignee + ')').join(', '));
}

// ── 5. PR Window server health ──
try {
  const prHealth = await helpers.httpRequest({ method: 'GET', url: 'http://127.0.0.1:8787/health' });
  if (!prHealth.ok) alerts.push('🔴 **PR Window server**: health check failed');
} catch(e) {
  alerts.push('🔴 **PR Window server (8787)**: not responding — LaunchAgent may be down');
}

// ── 6. In_progress issues stuck >4h (stale lane) ──
const fourHoursAgo = new Date(now - 4 * 60 * 60 * 1000).toISOString();
const stuckInProgress = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.in_progress&started_at=lt.' + fourHoursAgo + '&select=task_key,assignee,started_at&limit=5',
  headers: h
});
if (Array.isArray(stuckInProgress) && stuckInProgress.length > 0) {
  alerts.push('🟡 **In_progress >4h**: ' + stuckInProgress.map(i => '`' + i.task_key + '`(' + i.assignee + ')').join(', '));
}



// ── Auto-fix actions ──
// 1. Auto-reroute misassigned issues (don't wait for KAOS reroute workflow)
if (Array.isArray(misassigned) && misassigned.length > 0) {
  const TYPE_AGENT = { task: 'builder', bug: 'builder', feature: 'po', ops: 'ops', research: 'scout', review: 'tester' };
  for (const issue of misassigned) {
    const correct = TYPE_AGENT[issue.type];
    if (correct) {
      await helpers.httpRequest({
        method: 'PATCH',
        url: SUPA + '/rest/v1/issues?id=eq.' + issue.id,
        headers: { ...h, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ assignee: correct })
      });
    }
  }
}

// 2. Auto-trigger tester for stuck code_review issues
if (Array.isArray(stuckReview) && stuckReview.length > 0) {
  try {
    await helpers.httpRequest({
      method: 'POST', url: 'http://127.0.0.1:8787/trigger-agent',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentId: 'tester', message: 'Issues stuck in code_review need your review: ' + stuckReview.map(i => i.task_key).join(', ') + '. Check http://localhost:3000/api/issues for details. PATCH with tester_status=passed|failed + tester_notes.' })
    });
  } catch(e) {}
}

// 3. Create an issue for critical workflow failures (error streak >= 3)
const criticalWfFailures = alerts.filter(a => a.startsWith('🔴 **') && a.includes('errored'));
for (const failure of criticalWfFailures) {
  const wfName = failure.match(/\*\*(.+?)\*\*/)?.[1] || 'unknown';
  try {
    await helpers.httpRequest({
      method: 'POST', url: MC_API,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'CRITICAL: n8n workflow "' + wfName + '" error streak detected',
        description: failure,
        type: 'ops', project: 'Todero', priority: 'critical',
        assignee: 'ops', status: 'open', sprint: new Date().toISOString().split('T')[0],
        severity: 'S1', reviewer: 'auditor', owner: 'ops',
        acceptance_criteria: 'Fix the workflow error. Verify last 3 runs succeed.'
      })
    });
  } catch(e) {}
}

// ── Post results ──
if (alerts.length === 0) {
  return [{ json: { status: 'healthy', checks: 6, alerts: 0 } }];
}

const msg = '🔍 **Auditor Health Check** — ' + alerts.length + ' issue(s) found:\n\n' + alerts.join('\n') + '\n\n_' + new Date().toLocaleString('en-US', {timeZone:'America/New_York'}) + '_';

if (DISCORD_TOKEN) {
  await helpers.httpRequest({
    method: 'POST',
    url: 'https://discord.com/api/v10/channels/' + ALERT_CHANNEL + '/messages',
    headers: { Authorization: 'Bot ' + DISCORD_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: msg })
  });
}

return [{ json: { status: 'alerts', count: alerts.length, alerts } }];
